args <- commandArgs(trailingOnly = FALSE)
file_arg <- grep("^--file=", args, value = TRUE)
lab_dir <- if (length(file_arg)) dirname(normalizePath(sub("^--file=", "", file_arg[1]))) else normalizePath(getwd())
data_path <- function(name) file.path(lab_dir, "data", name)
out_path <- function(name) file.path(lab_dir, "outputs", name)
dir.create(out_path(""), recursive = TRUE, showWarnings = FALSE)
options(stringsAsFactors = FALSE)

h <- read.csv(data_path("health-research.csv")); palette<-c("#1F6FEB","#10B981","#7C3AED","#F59E0B")
png(out_path("lab-09-comparison.png"),1100,650,res=130); counts<-sort(table(h$chest_pain),decreasing=TRUE); barplot(counts,col=palette[seq_along(counts)],las=2,ylab="Observations",main="Chest-pain categories"); dev.off()
png(out_path("lab-09-distribution.png"),1100,650,res=130); boxplot(weight~smoker,h,col=palette[1:2],xlab="Smoking status",ylab="Weight (kg)",main="Weight distribution by smoking status"); stripchart(weight~smoker,h,vertical=TRUE,method="jitter",pch=19,add=TRUE,col="#161B26"); dev.off()
png(out_path("lab-09-relationship.png"),1100,650,res=130); cols<-palette[as.integer(factor(h$chest_pain))]; plot(h$cancer_cell,h$weight,pch=19,col=cols,xlab="Cancer-cell indicator",ylab="Weight (kg)",main="Relationship by chest-pain category"); abline(lm(weight~cancer_cell,h),col="#DC2626",lwd=2); legend("topright",legend=levels(factor(h$chest_pain)),col=palette[seq_along(levels(factor(h$chest_pain)))],pch=19,bty="n"); dev.off()
write.csv(data.frame(plot=c("comparison","distribution","relationship"),purpose=c("categorical comparison","compare group distributions","show numeric relationship"),limitation=c("small sample","group sizes differ","trend is associative")),out_path("lab-09-chart-audit.csv"),row.names=FALSE)
cat("Lab 9 complete\n")
